  priority?: 'LOW' | 'MEDIUM' | 'HIGH' | 'URGENT';
  isRead?: boolean;
  assignedToId?: string | number | null;
}

export type ContactRequestBulkAction =
  | 'delete'
  | 'restore'
  | 'hard-delete'
  | 'mark-read'
  | 'mark-unread'
  | 'update-status';

@Injectable()
export abstract class BaseContactRequestsService extends BaseCrudService<
  ContactRequestsRowDto,
  ContactRequestsCreateData,
  ContactRequestsUpdateData
> {
  protected readonly logger = new Logger(BaseContactRequestsService.name);
  protected abstract getEntity(): new () => Record<string, unknown>;
  protected getEntityName(): string {
    return 'ContactRequests';
  }
  protected getSearchFields(): string[] {
    return ['name', 'email', 'phone', 'subject', 'content'];
  }
  protected getFilterableFields(): string[] {
    return ['status', 'priority', 'isRead', 'assignedToId'];
  }
  protected getSoftDeleteField(): string | null {
    return 'deletedAt';
  }

  protected buildWhere(params: ListCrudParams): Record<string, unknown> {
    const where = super.buildWhere({
      ...params,
      status:
        params.status === 'deleted' || params.status === 'all'
          ? params.status
          : 'all',
    });

    if (
      params.status &&
      ['NEW', 'IN_PROGRESS', 'RESOLVED', 'CLOSED'].includes(params.status)
    ) {
      where.status = params.status;
      where.deletedAt = null;
    }

    return where;
  }

  async bulkAction(
    action: ContactRequestBulkAction,
    ids: string[],
    status?: ContactRequestsUpdateData['status'],
  ): Promise<{ affectedCount: number; message: string }> {
    if (!ids.length) {
      return { affectedCount: 0, message: 'Không có bản ghi nào' };
    }

    const em = this.getEm();
    const Entity = this.getEntity();
    const entityIds = toEntityIdList(ids);

    if (action === 'update-status' && status) {
      const result = await em.nativeUpdate(
        Entity,
        { id: { $in: entityIds }, deletedAt: null } as Record<string, unknown>,
        { status },
      );
      return {
        affectedCount: result ?? 0,
        message: `Đã cập nhật trạng thái ${result ?? 0} ban ghi`,
      };
    }

    if (action === 'mark-read') {
      const result = await em.nativeUpdate(
        Entity,
        {
          id: { $in: entityIds },
          deletedAt: null,
          isRead: false,
        } as Record<string, unknown>,
        { isRead: true },
      );
      return {
        affectedCount: result ?? 0,
        message: `Đã đánh dấu đã đọc ${result ?? 0} ban ghi`,
      };
    }

    if (action === 'mark-unread') {
      const result = await em.nativeUpdate(
        Entity,
        {
          id: { $in: entityIds },
          deletedAt: null,
          isRead: true,
        } as Record<string, unknown>,
        { isRead: false },
      );
      return {
        affectedCount: result ?? 0,
        message: `Đã đánh dấu chưa đọc ${result ?? 0} ban ghi`,
      };
    }

    if (action === 'delete') {
      const result = await em.nativeUpdate(
        Entity,
        { id: { $in: entityIds }, deletedAt: null } as Record<string, unknown>,
        { deletedAt: new Date() },
      );
      return {
        affectedCount: result ?? 0,
        message: `Đã xóa ${result ?? 0} ban ghi`,
      };
    }

    if (action === 'restore') {
      const result = await em.nativeUpdate(
        Entity,
        {
          id: { $in: entityIds },
          deletedAt: { $ne: null },
        } as Record<string, unknown>,
        { deletedAt: null },
      );
      return {
        affectedCount: result ?? 0,
        message: `Đã khôi phục ${result ?? 0} ban ghi`,
      };
    }

    if (action === 'hard-delete') {
      const result = await em.nativeDelete(Entity, {
        id: { $in: entityIds },
      } as Record<string, unknown>);
      return {
        affectedCount: result ?? 0,
        message: `Đã xóa vĩnh viễn ${result ?? 0} ban ghi`,
      };
    }

    return { affectedCount: 0, message: 'Action không hợp lệ' };
  }
}

import { Body, Controller, Post, Res } from '@nestjs/common';
import type { Response } from 'express';
import { Public, createErrorResponse, createSuccessResponse } from '../../index';
import { PUBLIC_ROUTES } from '../../../config/constants';;
import type { BaseContactRequestsService } from './contact-request.service';

export type CreatePublicContactRequestDto = {
  name?: string;
  fullName?: string;
  email: string;
  phone?: string;
  subject?: string;
  address?: string;
  program?: string;
  major?: string;
  subscribeNewsletter?: boolean;
  subscribeConsultation?: boolean;
  content?: string;
};

export type IPublicContactRequestsControllerService = Pick<
  BaseContactRequestsService,
  'create'
>;

@Public()
@Controller(PUBLIC_ROUTES.BASE)
export class BasePublicContactRequestsController {
  constructor(private readonly service: IPublicContactRequestsControllerService) {}

  @Post('contact-requests')
  async createContactRequest(
    @Body() body: CreatePublicContactRequestDto,
    @Res() res: Response,
  ): Promise<Response> {
    const name = body?.name?.trim() || body?.fullName?.trim();
    const email = body?.email?.trim();
    const subject = body?.subject?.trim();
    const hasLegacyConsultationFields = Boolean(
      body?.address ||
        body?.program ||
        body?.major ||
        body?.subscribeNewsletter ||
        body?.subscribeConsultation,
    );

    if (!name || !email || (!subject && !hasLegacyConsultationFields)) {
      const { statusCode, body: errBody } = createErrorResponse(
        'Vui long dien day du ho ten, email va chu de lien he.',
        { status: 400 },
      );
      return res.status(statusCode).json(errBody);
    }

    try {
      const resolvedSubject = subject
        ? subject
        : hasLegacyConsultationFields
          ? 'Dang ky tu van tuyen sinh'
          : 'Lien he ho tro';

      const parts: string[] = [];
      if (body.address) parts.push(`Dia chi: ${body.address}`);
      if (body.program) parts.push(`Chuong trinh: ${body.program}`);
      if (body.major) parts.push(`Nganh: ${body.major}`);
      if (body.subscribeNewsletter)
        parts.push('Dang ky nhan thong tin tuyen sinh: Co');
      if (body.subscribeConsultation) parts.push('Dang ky tu van: Co');
      if (body.content?.trim()) parts.push(`Noi dung: ${body.content.trim()}`);
      const content = parts.length > 0 ? parts.join('\n') : 'Khong co noi dung them';

      const created = await this.service.create({
        name,
        email,
        phone: body.phone?.trim() ? body.phone.trim() : null,
        subject: resolvedSubject,
        content,
        status: 'NEW',
        isRead: false,
      } as never);

      const { statusCode, body: okBody } = createSuccessResponse({
        id: String((created as unknown as { id?: string | number }).id ?? ''),
        message: 'Gui lien he thanh cong. Chung toi se phan hoi ban som.',
      });
      return res.status(statusCode).json(okBody);
    } catch {
      const { statusCode, body: errBody } = createErrorResponse(
        'Khong the gui lien he ho tro. Vui long thu lai sau.',
        { status: 500 },
      );
      return res.status(statusCode).json(errBody);
    }
  }
}

