import type { EntityName } from '@mikro-orm/core';
import type { EventRegistrationRowDto } from './event-registrations.service';
import type { EventAttendanceSocketPayload } from './event-registration-attendance.types';

export interface EventRegistrationAttendanceDeps {
  eventEntity: EntityName<Record<string, unknown>>;
  eventRegistrationEntity: EntityName<Record<string, unknown>>;
  getRegistrationById(id: string): Promise<EventRegistrationRowDto | null>;
  emitAttendance(payload: EventAttendanceSocketPayload): void;
}

/** Event registration attendance — check-in/out; app binding entity, socket emit, getById. */
import {
  BadRequestException,
  Logger,
  NotFoundException,
} from '@nestjs/common';
import { EntityManager, type FilterQuery } from '@mikro-orm/core';
import { relationEntityId, toEntityId } from '../../entity-id';
import type { EventRegistrationAttendanceDeps } from './event-registration-attendance.deps';
import type {
  ApplyAttendanceResult,
  AttendanceRegistrationRow,
  AttendanceSource,
  EventAttendancePolicy,
  EventAttendanceSocketPayload,
  ManualAttendanceAction,
} from './event-registration-attendance.types';
import {
  ATTENDANCE_STATUS,
  CHECKIN_METHOD,
  REGISTRATION_STATUS,
} from './event-registration-attendance.types';
import type { EventRegistrationRowDto } from './event-registrations.service';

export class BaseEventRegistrationAttendanceService {
  private readonly logger = new Logger(BaseEventRegistrationAttendanceService.name);

  constructor(
    protected readonly em: EntityManager,
    protected readonly deps: EventRegistrationAttendanceDeps,
  ) {}

  async applyManual(
    registrationId: string,
    action: ManualAttendanceAction,
  ): Promise<EventRegistrationRowDto> {
    const reg = await this.em.findOne(
      this.deps.eventRegistrationEntity,
      {
        id: toEntityId(registrationId),
        deletedAt: null,
      } as FilterQuery<Record<string, unknown>>,
    );
    if (!reg) {
      throw new NotFoundException('Không tìm thấy đăng ký sự kiện');
    }

    const row = reg as unknown as AttendanceRegistrationRow;
    const eventId = relationEntityId(row.event);
    if (eventId == null) {
      throw new BadRequestException('Đăng ký không gắn sự kiện hợp lệ');
    }

    const at = new Date();

    switch (action) {
      case 'checkin': {
        await this.recordCheckin({
          eventId,
          registration: row,
          at,
          source: 'manual',
          skipWindowCheck: true,
        });
        break;
      }
      case 'checkout': {
        await this.recordCheckout({
          eventId,
          registration: row,
          at,
          source: 'manual',
          skipWindowCheck: true,
        });
        break;
      }
      case 'reset-checkin':
        row.hasCheckin = false;
        row.checkinMethod = CHECKIN_METHOD.NONE;
        if (row.hasCheckout) {
          row.hasCheckout = false;
        }
        row.attendanceStatus = ATTENDANCE_STATUS.NOT_ATTENDED;
        row.updatedAt = at;
        await this.em.flush();
        await this.syncEventCounts(eventId);
        this.emitState(row, eventId, 'checkin', 'manual', { duplicate: false });
        break;
      case 'reset-checkout':
        row.hasCheckout = false;
        row.attendanceStatus = row.hasCheckin
          ? ATTENDANCE_STATUS.PARTIAL
          : ATTENDANCE_STATUS.NOT_ATTENDED;
        row.updatedAt = at;
        await this.em.flush();
        await this.syncEventCounts(eventId);
        this.emitState(row, eventId, 'checkout', 'manual', {
          duplicate: false,
        });
        break;
      case 'reset-all':
        row.hasCheckin = false;
        row.hasCheckout = false;
        row.checkinMethod = CHECKIN_METHOD.NONE;
        row.attendanceStatus = ATTENDANCE_STATUS.NOT_ATTENDED;
        row.updatedAt = at;
        await this.em.flush();
        await this.syncEventCounts(eventId);
        this.emitState(row, eventId, 'checkin', 'manual', { duplicate: false });
        break;
      default:
        throw new BadRequestException('Thao tác attendance không hợp lệ');
    }

    const mapped = await this.deps.getRegistrationById(registrationId);
    if (!mapped) {
      throw new NotFoundException('Không tìm thấy đăng ký sự kiện');
    }
    return mapped;
  }

  async recordCheckin(input: {
    eventId: number;
    registration: AttendanceRegistrationRow;
    at: Date;
    source: AttendanceSource;
    deviceId?: string | null;
    deviceName?: string | null;
    skipWindowCheck?: boolean;
  }): Promise<ApplyAttendanceResult> {
    const { eventId, registration: reg, at, source } = input;
    if (!input.skipWindowCheck) {
      const event = await this.loadEvent(eventId);
      this.assertEventAllows(event, 'checkin', at);
    }

    if (reg.hasCheckin) {
      this.logger.debug(
        `Attendance check-in bỏ qua (đã check-in) event=${eventId} email=${reg.email}`,
      );
      const result = await this.toResult(eventId, reg, 'checkin', true);
      this.emitState(reg, eventId, 'checkin', source, {
        duplicate: true,
        deviceId: input.deviceId,
        deviceName: input.deviceName,
      });
      return result;
    }

    reg.hasCheckin = true;
    reg.faceVerified = source === 'hanet' ? true : reg.faceVerified;
    reg.checkinMethod =
      source === 'manual' ? CHECKIN_METHOD.MANUAL : CHECKIN_METHOD.FACE_ID;
    reg.updatedAt = at;
    if (reg.status === REGISTRATION_STATUS.PENDING) {
      reg.status = REGISTRATION_STATUS.CONFIRMED;
    }
    if (reg.attendanceStatus === ATTENDANCE_STATUS.NOT_ATTENDED) {
      reg.attendanceStatus = ATTENDANCE_STATUS.PARTIAL;
    }
    await this.em.flush();
    await this.syncEventCounts(eventId);

    const result = await this.toResult(eventId, reg, 'checkin', false);
    this.emitState(reg, eventId, 'checkin', source, {
      duplicate: false,
      deviceId: input.deviceId,
      deviceName: input.deviceName,
    });
    this.logger.log(
      `Attendance check-in (${source}) event=${eventId} email=${reg.email}`,
    );
    return result;
  }

  async recordCheckout(input: {
    eventId: number;
    registration: AttendanceRegistrationRow;
    at: Date;
    source: AttendanceSource;
    skipWindowCheck?: boolean;
  }): Promise<ApplyAttendanceResult> {
    const { eventId, registration: reg, at, source } = input;
    if (!input.skipWindowCheck) {
      const event = await this.loadEvent(eventId);
      this.assertEventAllows(event, 'checkout', at);
    }

    if (reg.hasCheckout) {
      this.logger.debug(
        `Attendance check-out bỏ qua (đã check-out) event=${eventId} email=${reg.email}`,
      );
      const result = await this.toResult(eventId, reg, 'checkout', true);
      this.emitState(reg, eventId, 'checkout', source, { duplicate: true });
      return result;
    }

    if (!reg.hasCheckin) {
      reg.hasCheckin = true;
      if (reg.attendanceStatus === ATTENDANCE_STATUS.NOT_ATTENDED) {
        reg.attendanceStatus = ATTENDANCE_STATUS.PARTIAL;
      }
    }

    reg.hasCheckout = true;
    reg.faceVerified = source === 'hanet' ? true : reg.faceVerified;
    reg.attendanceStatus = ATTENDANCE_STATUS.FULL;
    reg.updatedAt = at;
    await this.em.flush();
    await this.syncEventCounts(eventId);

    const result = await this.toResult(eventId, reg, 'checkout', false);
    this.emitState(reg, eventId, 'checkout', source, { duplicate: false });
    this.logger.log(
      `Attendance check-out (${source}) event=${eventId} email=${reg.email}`,
    );
    return result;
  }

  private async loadEvent(eventId: number): Promise<EventAttendancePolicy> {
    const event = await this.em.findOne(this.deps.eventEntity, {
      id: eventId,
      deletedAt: null,
    } as FilterQuery<Record<string, unknown>>);
    if (!event) {
      throw new NotFoundException('Không tìm thấy sự kiện');
    }
    return event as unknown as EventAttendancePolicy;
  }

  private assertEventAllows(
    event: EventAttendancePolicy,
    kind: 'checkin' | 'checkout',
    at: Date,
  ): void {
    if (kind === 'checkin' && !event.allowCheckin) {
      throw new BadRequestException('Sự kiện không cho phép check-in');
    }
    if (kind === 'checkout' && !event.allowCheckout) {
      throw new BadRequestException('Sự kiện không cho phép check-out');
    }

    const within = (start?: Date | null, end?: Date | null) => {
      if (start && at < start) return false;
      if (end && at > end) return false;
      return true;
    };

    if (kind === 'checkin') {
      if (
        (event.checkinStart || event.checkinEnd) &&
        !within(event.checkinStart, event.checkinEnd)
      ) {
        throw new BadRequestException(
          'Thời điểm check-in nằm ngoài khung giờ cho phép',
        );
      }
      return;
    }

    const windowStart = event.checkoutStart ?? event.checkinEnd ?? null;
    const windowEnd = event.checkoutEnd ?? event.endDate ?? null;
    if ((windowStart || windowEnd) && !within(windowStart, windowEnd)) {
      throw new BadRequestException(
        'Thời điểm check-out nằm ngoài khung giờ cho phép',
      );
    }
  }

  private async syncEventCounts(eventId: number): Promise<void> {
    const checkinCount = await this.em.count(this.deps.eventRegistrationEntity, {
      event: eventId,
      hasCheckin: true,
      deletedAt: null,
    } as FilterQuery<Record<string, unknown>>);
    const checkoutCount = await this.em.count(this.deps.eventRegistrationEntity, {
      event: eventId,
      hasCheckout: true,
      deletedAt: null,
    } as FilterQuery<Record<string, unknown>>);
    await this.em.nativeUpdate(
      this.deps.eventEntity,
      { id: eventId },
      { totalCheckins: checkinCount, totalCheckouts: checkoutCount },
    );
  }

  private async toResult(
    eventId: number,
    reg: AttendanceRegistrationRow,
    kind: 'checkin' | 'checkout',
    duplicate: boolean,
  ): Promise<ApplyAttendanceResult> {
    const mapped = await this.deps.getRegistrationById(String(reg.id));
    if (!mapped) {
      throw new NotFoundException('Không tìm thấy đăng ký sự kiện');
    }
    return {
      kind,
      eventId,
      email: reg.email,
      fullName: reg.fullName,
      registrationId: reg.id,
      at: reg.updatedAt.toISOString(),
      duplicate,
      registration: mapped,
    };
  }

  private emitState(
    reg: AttendanceRegistrationRow,
    eventId: number,
    kind: 'checkin' | 'checkout',
    source: AttendanceSource,
    extra: {
      duplicate?: boolean;
      deviceId?: string | null;
      deviceName?: string | null;
    },
  ): void {
    const payload: EventAttendanceSocketPayload = {
      kind,
      eventId,
      at: reg.updatedAt.toISOString(),
      email: reg.email,
      fullName: reg.fullName,
      source,
      deviceId: extra.deviceId ?? null,
      deviceName: extra.deviceName ?? null,
      registrationId: reg.id,
      checkinId: null,
      duplicate: extra.duplicate,
      hasCheckin: reg.hasCheckin,
      hasCheckout: reg.hasCheckout,
    };
    this.deps.emitAttendance(payload);
  }
}

import type { EventRegistrationRowDto } from './event-registrations.service';

export type AttendanceSource = 'hanet' | 'manual';

export type ManualAttendanceAction =
  | 'checkin'
  | 'checkout'
  | 'reset-checkin'
  | 'reset-checkout'
  | 'reset-all';

export type ApplyAttendanceResult = {
  kind: 'checkin' | 'checkout';
  eventId: number;
  email: string;
  fullName: string;
  registrationId: number;
  at: string;
  duplicate?: boolean;
  registration: EventRegistrationRowDto;
};

export type EventAttendanceSocketPayload = {
  kind: 'checkin' | 'checkout';
  eventId: number;
  at: string;
  email: string;
  fullName: string;
  source: AttendanceSource;
  deviceId?: string | null;
  deviceName?: string | null;
  registrationId?: string | number | null;
  checkinId?: string | null;
  duplicate?: boolean;
  hasCheckin?: boolean;
  hasCheckout?: boolean;
};

/** Khớp `RegistrationStatus` entity. */
export const REGISTRATION_STATUS = {
  PENDING: 0,
  CONFIRMED: 1,
  CANCELLED: 2,
} as const;

/** Khớp `AttendanceStatus` entity. */
export const ATTENDANCE_STATUS = {
  NOT_ATTENDED: 0,
  PARTIAL: 1,
  FULL: 2,
} as const;

/** Khớp `CheckinMethod` entity. */
export const CHECKIN_METHOD = {
  NONE: 0,
  QR_CODE: 1,
  FACE_ID: 2,
  MANUAL: 3,
} as const;

export type EventAttendancePolicy = {
  allowCheckin: boolean;
  allowCheckout: boolean;
  checkinStart?: Date | null;
  checkinEnd?: Date | null;
  checkoutStart?: Date | null;
  checkoutEnd?: Date | null;
  endDate?: Date | null;
};

export type AttendanceRegistrationRow = {
  id: number;
  email: string;
  fullName: string;
  event: unknown;
  hasCheckin: boolean;
  hasCheckout: boolean;
  faceVerified: boolean;
  checkinMethod: number;
  attendanceStatus: number;
  status: number;
  updatedAt: Date;
};

/**
 * BaseEventRegistrationsController — HTTP admin event registrations.
 */
import {
  ApiTags,
  ApiOperation,
  ApiHeader,
  ApiBody,
  ApiResponse,
} from '@nestjs/swagger';
import {
  Controller,
  Get,
  Post,
  Put,
  Delete,
  Body,
  Param,
  Query,
  Headers,
  Res,
} from '@nestjs/common';
import type { Response } from 'express';
import { BaseAdminHttpController } from '../../crud/base-admin-http.controller';
import { Permissions, parseAdminListLimit, isBulkAction } from '../../index';
import { ADMIN_ROUTES } from '../../../config/constants';
import { PERMISSIONS } from '../../../config/permissions';;
import type { BaseEventRegistrationsService } from './event-registrations.service';
import type { ManualAttendanceAction } from './event-registration-attendance.types';
import type { BaseEventRegistrationAttendanceService } from './event-registration-attendance.service';

export type IEventRegistrationsControllerService = Pick<
  BaseEventRegistrationsService,
  | 'syncEventRegistrationCount'
  | 'list'
  | 'getById'
  | 'create'
  | 'update'
  | 'hardDelete'
  | 'softDelete'
  | 'restore'
  | 'bulk'
>;
/** @deprecated Dùng `IEventRegistrationsControllerService`. */
export type IEventRegistrationsAdminControllerService = IEventRegistrationsControllerService;

@ApiTags('Event Registrations')
@Permissions(PERMISSIONS.EVENT_REGISTRATIONS_VIEW)
@Controller(ADMIN_ROUTES.EVENT_REGISTRATIONS)
export class BaseEventRegistrationsController extends BaseAdminHttpController {
  constructor(
    protected readonly service: IEventRegistrationsControllerService,
    protected readonly attendanceService: BaseEventRegistrationAttendanceService,
  ) {
    super();
  }

  @Get()
  @ApiOperation({ summary: 'List event registrations with pagination' })
  @ApiHeader({ name: 'X-User-Id', required: true })
  async list(
    @Res() res: Response,
    @Headers() headers: Record<string, string | undefined>,
    @Query('eventId') eventId?: string,
    @Query('page') page?: string,
    @Query('limit') limit?: string,
    @Query('search') search?: string,
    @Query('status') status?: string,
  ) {
    const userId = this.requireUserId(res, headers);
    if (typeof userId !== 'string') return userId;
    if (!eventId?.trim()) {
      return this.sendError(res, 'eventId là bắt buộc', 400);
    }

    const trimmedEventId = eventId.trim();
    await this.service.syncEventRegistrationCount(trimmedEventId);
    const result = await this.service.list({
      eventId: trimmedEventId,
      page: Math.max(1, parseInt(String(page), 10) || 1),
      limit: parseAdminListLimit(limit, 10),
      search: search?.trim(),
      status: status?.trim(),
    });
    return this.sendSuccess(res, {
      data: result.data,
      pagination: result.pagination,
    });
  }

  @Get(':id')
  @ApiOperation({ summary: 'Get event registration by ID' })
  @ApiHeader({ name: 'X-User-Id', required: true })
  async getById(
    @Res() res: Response,
    @Headers() headers: Record<string, string | undefined>,
    @Param('id') id: string,
  ) {
    const userId = this.requireUserId(res, headers);
    if (typeof userId !== 'string') return userId;

    const row = await this.service.getById(id);
    if (!row) return this.sendNotFound(res, 'Không tìm thấy đăng ký sự kiện');
    return this.sendSuccess(res, row);
  }

  @Post()
  @Permissions(PERMISSIONS.EVENT_REGISTRATIONS_CREATE)
  @ApiOperation({ summary: 'Create new event registration' })
  @ApiHeader({ name: 'X-User-Id', required: true })
  async create(
    @Res() res: Response,
    @Headers() headers: Record<string, string | undefined>,
    @Body()
    body: {
      eventId: string;
      email: string;
      fullName: string;
      phone?: string;
    },
  ) {
    const userId = this.requireUserId(res, headers);
    if (typeof userId !== 'string') return userId;
    if (!body?.eventId?.trim()) {
      return this.sendError(res, 'eventId là bắt buộc', 400);
    }
    if (!body?.email?.trim()) {
      return this.sendError(res, 'email là bắt buộc', 400);
    }
    if (!body?.fullName?.trim()) {
      return this.sendError(res, 'fullName là bắt buộc', 400);
    }

    const created = await this.service.create({
      eventId: body.eventId.trim(),
      email: body.email.trim(),
      fullName: body.fullName.trim(),
      phone: body.phone?.trim() ?? null,
    });
    return this.sendSuccess(res, created, { status: 201 });
  }

  @Post(':id/attendance')
  @Permissions(PERMISSIONS.EVENT_REGISTRATIONS_UPDATE)
  @ApiOperation({ summary: 'Cập nhật trạng thái check-in/out thủ công' })
  @ApiHeader({ name: 'X-User-Id', required: true })
  async setAttendance(
    @Res() res: Response,
    @Headers() headers: Record<string, string | undefined>,
    @Param('id') id: string,
    @Body() body: { action?: ManualAttendanceAction },
  ) {
    const userId = this.requireUserId(res, headers);
    if (typeof userId !== 'string') return userId;

    const action = body?.action;
    const allowed: ManualAttendanceAction[] = [
      'checkin',
      'checkout',
      'reset-checkin',
      'reset-checkout',
      'reset-all',
    ];
    if (!action || !allowed.includes(action)) {
      return this.sendError(
        res,
        'action phải là checkin | checkout | reset-checkin | reset-checkout | reset-all',
        400,
      );
    }

    const updated = await this.attendanceService.applyManual(id, action);
    return this.sendSuccess(res, updated);
  }

  @Put(':id')
  @Permissions(PERMISSIONS.EVENT_REGISTRATIONS_UPDATE)
  @ApiOperation({ summary: 'Update event registration by ID' })
  @ApiHeader({ name: 'X-User-Id', required: true })
  async update(
    @Res() res: Response,
    @Headers() headers: Record<string, string | undefined>,
    @Param('id') id: string,
    @Body()
    body: {
      email?: string;
      fullName?: string;
      phone?: string;
      status?: number;
      faceVerified?: boolean;
      attendanceStatus?: number;
      checkinMethod?: number;
    },
  ) {
    const userId = this.requireUserId(res, headers);
    if (typeof userId !== 'string') return userId;

    const updated = await this.service.update(id, {
      email: body?.email?.trim(),
      fullName: body?.fullName?.trim(),
      phone:
        body?.phone !== undefined ? (body.phone?.trim() ?? null) : undefined,
      status: body?.status,
      faceVerified: body?.faceVerified,
      attendanceStatus: body?.attendanceStatus,
      checkinMethod: body?.checkinMethod,
    });
    if (!updated) return this.sendNotFound(res, 'Không tìm thấy đăng ký sự kiện');
    return this.sendSuccess(res, updated);
  }

  @Delete(':id/hard-delete')
  @Permissions(PERMISSIONS.EVENT_REGISTRATIONS_HARD_DELETE)
  async hardDelete(
    @Res() res: Response,
    @Headers() headers: Record<string, string | undefined>,
    @Param('id') id: string,
  ) {
    return this.handleBoolMutation(
      res,
      headers,
      () => this.service.hardDelete(id),
      'Đã xóa vĩnh viễn đăng ký sự kiện',
      'Không tìm thấy đăng ký sự kiện',
    );
  }

  @Delete(':id')
  @Permissions(PERMISSIONS.EVENT_REGISTRATIONS_DELETE)
  async softDelete(
    @Res() res: Response,
    @Headers() headers: Record<string, string | undefined>,
    @Param('id') id: string,
  ) {
    return this.handleBoolMutation(
      res,
      headers,
      () => this.service.softDelete(id),
      'Đã xóa đăng ký sự kiện',
      'Đăng ký không tồn tại hoặc đã bị xóa',
    );
  }

  @Post(':id/restore')
  @Permissions(PERMISSIONS.EVENT_REGISTRATIONS_RESTORE)
  async restore(
    @Res() res: Response,
    @Headers() headers: Record<string, string | undefined>,
    @Param('id') id: string,
  ) {
    return this.handleBoolMutation(
      res,
      headers,
      () => this.service.restore(id),
      'Đã khôi phục đăng ký sự kiện',
      'Đăng ký không tồn tại hoặc chưa bị xóa',
    );
  }

  @Post('bulk')
  @Permissions(PERMISSIONS.EVENT_REGISTRATIONS_MANAGE)
  @ApiOperation({ summary: 'Bulk action on event registrations' })
  @ApiHeader({ name: 'X-User-Id', required: true })
  @ApiBody({ description: 'Bulk action with ids' })
  @ApiResponse({ status: 200, description: 'Bulk action completed' })
  async bulk(
    @Res() res: Response,
    @Headers() headers: Record<string, string | undefined>,
    @Body() body: { action?: string; ids?: string[] },
  ) {
    const userId = this.requireUserId(res, headers);
    if (typeof userId !== 'string') return userId;

    const action = body?.action;
    const ids = Array.isArray(body?.ids) ? body.ids : [];
    if (!action || !isBulkAction(action)) {
      return this.sendError(res, 'Action không hợp lệ', 400);
    }

    const result = await this.service.bulk(action, ids);
    return this.sendSuccess(
      res,
      { affected: result.affected, message: result.message },
      { message: result.message },
    );
  }
}

/**
 * EventRegistrations Module — NestJS wiring cho admin event-registrations.
 */
import { Module, type ModuleMetadata } from '@nestjs/common';
