} from '../../entity-id';
import { safeIsoString, safeIsoStringNow } from '../../date-utils';

export interface AuthRoleNamesBinding {
  USER: string;
  ADMIN: string;
  SUPER_ADMIN: string;
}

export interface SessionRowDto {
