        const { statusCode, body } = createSuccessResponse({
          studentCode,
          semesters: [],
          message: 'EXTERNAL_API_URL chưa được cấu hình',
        });
        return res.status(statusCode).json(body);
      }

      const fetchHeaders: Record<string, string> = {
        'Content-Type': 'application/json',
