  Query,
  Res,
  Logger,
} from '@nestjs/common';
import type { Response } from 'express';
import { ProductsService } from './products.service';
import { createSuccessResponse, createErrorResponse } from '../common';
import { PUBLIC_ROUTES } from '../config/constants';
